    public static final String[] k = new String[]{"\u5929\u5916\u6d41\u661f|\u8f69\u4e2d\u95e8\u4e0a\u5c42\u6b66\u529f,\u5c06\u4f53\u5185\u7684\u6c14\u529b\u805a\u96c6\u6210\u5f39\u4e38\u5411\u5468\u56f4\u53d1\u5c04.\u968f\u673a\u653b\u51fb\u5168\u5c4f\u4e0a\u6240\u6709\u654c\u4eba,\u9020\u6210\u5c11\u91cf\u4f24\u5bb3.\u4f7f\u7528\u6b64\u62db\u5f0f\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u72ec\u5b64\u5251\u9635|\u6b66\u771f\u6d3e\u9547\u6d3e\u4e4b\u5b9d,\u5c06\u5185\u529b\u5316\u6210\u5251\u6c14\u7684\u5f3a\u5927\u6b66\u529f,\u7531\u5251\u6c14\u5f62\u6210\u5251\u9635.\u5728\u5251\u9635\u4e2d\u7684\u654c\u4eba\u53d7\u5230\u5927\u91cf\u7684\u4f24\u5bb3.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u518d\u6309\u65b9\u5411\u952e(2468\u952e)\u5f62\u6210\u5251\u9635,\u5426\u5219\u65e0\u6cd5\u8fde\u6210\u5251\u9635.", "\u7384\u7956\u7206\u708e|\u6b66\u771f\u6d3e\u4e0a\u5c42\u6b66\u529f,\u9707\u51fb\u5730\u9762\u5f15\u53d1\u5f3a\u70c8\u7684\u51b2\u51fb\u653b\u51fb\u5468\u56f4\u7684\u654c\u4eba.\u5728\u5343\u519b\u4e07\u9a6c\u4e2d\u6240\u5411\u7765\u7768.\u65e0\u9700\u84c4\u529b\u5373\u53ef\u4f7f\u7528.", "\u7384\u7956\u706d\u9f99|\u5c06\u5185\u529b\u5168\u90e8\u96c6\u4e2d\u5728\u5251\u5203\u4e4b\u4e0a,\u5728\u5251\u5203\u4e0a\u5f62\u6210\u706b\u7130\u822c\u7684\u5251\u6c14\u7ed9\u4e88\u654c\u4eba\u6700\u5f3a\u7684\u4e00\u51fb,\u5355\u4f53\u6740\u4f24\u529b\u6781\u5927.\u4f7f\u7528\u65f6\u9700\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u6b66\u795e\u771f\u6c14|\u6b66\u771f\u6d3e\u4e0a\u5c42\u8f7b\u529f,\u771f\u6c14\u9644\u4f53,\u53ef\u5927\u5e45\u5ea6\u7684\u63d0\u9ad8\u81ea\u8eab\u7684\u79fb\u52a8\u901f\u5ea6.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u62a4\u8eab\u5f3a\u6c14|\u5728\u81ea\u5df1\u7684\u9762\u524d\u53ec\u5524\u51fa\u77f3\u67f1\u6765\u963b\u6321\u654c\u4eba\u7684\u8fdb\u653b,\u672c\u8eab\u4e0d\u5177\u5907\u653b\u51fb\u6027.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u6c14\u529f\u6ce2|\u6b66\u771f\u7edd\u5b66.\u628a\u4f53\u5185\u7684\u6c14\u529b\u805a\u96c6\u5728\u638c\u4e2d\u91ca\u653e\u51fa\u5f3a\u5927\u7684\u51b2\u51fb\u6ce2\u653b\u51fb\u4e00\u6761\u76f4\u7ebf\u4e0a\u7684\u6240\u6709\u654c\u4eba.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u6df7\u6c8c\u5929\u9b54|\u72ec\u5b64\u8001\u4eba\u81ea\u521b\u7684\u90aa\u6076\u6b66\u529f.\u53ef\u4ee5\u5438\u6536\u654c\u4eba\u7684\u4f53\u529b\u8f6c\u5316\u4e3a\u81ea\u5df1\u7684\u4f53\u529b\u503c.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u771f\u9f99\u5486\u54ee|\u5927\u543c\u4e00\u58f0\u5c06\u5185\u529b\u91ca\u653e\u51fa\u53bb,\u4f7f\u5927\u9762\u79ef\u7684\u654c\u4eba\u7729\u6655.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b\uff0c\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u864e\u54ee\u51fb|\u5c06\u4f53\u5185\u7684\u6c14\u529b\u5916\u653e,\u4f7f\u56db\u5468\u7684\u654c\u4eba\u7729\u6655.\u65e0\u9700\u84c4\u529b\u5373\u53ef\u91ca\u653e.", "\u6b66\u795e\u771f\u6c14|\u6b66\u771f\u6d3e\u4e0a\u5c42\u8f7b\u529f,\u771f\u6c14\u9644\u4f53,\u53ef\u5927\u5e45\u5ea6\u7684\u63d0\u9ad8\u81ea\u8eab\u7684\u79fb\u52a8\u901f\u5ea6.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e.", "\u62a4\u8eab\u5f3a\u6c14|\u5728\u81ea\u5df1\u7684\u9762\u524d\u53ec\u5524\u51fa\u77f3\u67f1\u6765\u963b\u6321\u654c\u4eba\u7684\u8fdb\u653b,\u672c\u8eab\u4e0d\u5177\u5907\u653b\u51fb\u6027.\u4f7f\u7528\u65f6\u9700\u8981\u6309\u4f4f\u6280\u80fd\u952e\u8fdb\u884c\u84c4\u529b,\u84c4\u529b\u69fd\u5145\u6ee1\u540e\u6280\u80fd\u91ca\u653e."};
    public static final String[] l = new String[]{"\u771f\u708e\u5251|\u51fa\u5251\u540e\u4f1a\u91ca\u653e\u51fa\u706b\u4e00\u6837\u7684\u5251\u6c14\u653b\u51fb\u4e00\u6761\u76f4\u7ebf\u4e0a\u7684\u654c\u4eba.", "\u6d41\u51b0\u5251|\u51fa\u5251\u540e\u4f1a\u91ca\u653e\u51fa\u65cb\u98ce\u5251\u6c14\u653b\u51fb\u56db\u5468\u7684\u654c\u4eba.", "\u5929\u96f7\u5251|\u51fa\u5251\u540e\u4f1a\u53ec\u5524\u5929\u96f7\u653b\u51fb\u5355\u4e2a\u654c\u4eba,\u5a01\u529b\u5de8\u5927.", "\u5c60\u9f99\u771f\u708e|\u7531\u771f\u708e\u5251\u8fdb\u5316\u800c\u6765,\u7528\u706b\u7130\u76f4\u63a5\u653b\u51fb\u4e00\u6761\u76f4\u7ebf\u4e0a\u7684\u654c\u4eba,\u9020\u6210\u5f3a\u5927\u7684\u4f24\u5bb3.", "\u7834\u5929\u5bd2\u51b0|\u7531\u6d41\u51b0\u5251\u8fdb\u5316\u800c\u6765,\u7528\u51b0\u5c5e\u6027\u7684\u65cb\u98ce\u76f4\u63a5\u653b\u51fb\u5468\u56f4\u7684\u654c\u4eba,\u9020\u6210\u5927\u91cf\u4f24\u5bb3.", "\u5949\u5929\u60ca\u96f7|\u7531\u5929\u96f7\u5251\u8fdb\u5316\u800c\u6765,\u53ec\u5524\u5929\u4e0a\u7684\u843d\u96f7\u76f4\u63a5\u653b\u51fb\u5355\u4e2a\u654c\u4eba,\u4e00\u51fb\u7834\u654c\u6740\u4f24\u6781\u5927.", "\u706b\u795e\u62f3|\u51fa\u62f3\u540e\u5411\u56db\u5468\u91ca\u653e\u51fa\u4e0d\u65ad\u71c3\u70e7\u7684\u706b\u7130\u653b\u51fb\u654c\u4eba.", "\u901f\u51b0\u62f3|\u51fa\u62f3\u540e\u5411\u524d\u65b9\u6253\u51fa\u8fde\u7eed\u7684\u51b0\u5c5e\u6027\u62f3\u6cd5.\u653b\u51fb\u6301\u7eed,\u4f24\u5bb3\u5de8\u5927.", "\u96f7\u4e91\u62f3|\u5c06\u96f7\u7684\u529b\u91cf\u5b9e\u4f53\u5316,\u5728\u51fa\u62f3\u540e\u6253\u51fa\u5de8\u62f3\u5f62\u6001\u7684\u96f7\u5c5e\u6027\u62f3\u6cd5.", "\u706d\u4e16\u706b\u795e\u62f3|\u7531\u706b\u795e\u62f3\u8fdb\u5316\u800c\u6765,\u76f4\u63a5\u91ca\u653e\u706b\u7130\u6301\u7eed\u71c3\u70e7\u653b\u51fb\u56db\u5468\u7684\u654c\u4eba.", "\u4e91\u6c34\u901f\u51b0\u62f3|\u7531\u901f\u51b0\u62f3\u8fdb\u5316\u800c\u6765,\u76f4\u63a5\u7528\u51b0\u5c5e\u6027\u7684\u62f3\u8fde\u7eed\u653b\u51fb\u524d\u65b9\u7684\u654c\u4eba.", "\u5949\u5929\u96f7\u4e91\u62f3|\u7531\u96f7\u4e91\u62f3\u8fdb\u5316\u800c\u6765,\u76f4\u63a5\u7528\u96f7\u5c5e\u6027\u7684\u5de8\u62f3\u653b\u51fb\u524d\u65b9\u7684\u654c\u4eba,\u4f24\u5bb3\u5de8\u5927."};
    public static final String[] m = new String[]{"\u9053\u58eb\u5fc3\u6cd5|\u589e\u52a0\u529b\u91cf.", "\u6b66\u771f\u5fc3\u6cd5|\u8840\u8109\u8d2f\u901a\u589e\u52a0\u8fd0\u6c14\u7684\u901f\u5ea6.", "\u9b54\u6559\u5fc3\u6cd5|\u4f53\u529b\u4e0a\u5347.", "\u795e\u58eb\u5fc3\u6cd5|\u4fee\u70bc\u65f6\u589e\u52a0\u529b\u91cf,\u4f53\u529b,\u8fd0\u6c14\u901f\u5ea6.", "\u9053\u58eb\u5fc3\u6cd5|\u4fee\u70bc\u9053\u58eb\u5fc3\u6cd5\u53ef\u4ee5\u8ba9\u6c14\u529b\u6e05\u65b0,\u5185\u529b\u589e\u52a0.", "\u6b66\u771f\u5fc3\u6cd5|\u4fee\u70bc\u6b66\u771f\u6d3e\u7684\u4e0a\u4e58\u5fc3\u6cd5\u53ef\u4ee5\u6253\u901a\u4f53\u5185\u7684\u7a74\u9053,\u589e\u52a0\u8fd0\u6c14\u901f\u5ea6.", "\u9b54\u6559\u5fc3\u6cd5|\u4fee\u70bc\u9b54\u6559\u7684\u4e0a\u4e58\u5fc3\u6cd5\u53ef\u4ee5\u53d8\u5f97\u50cf\u96f7\u4e00\u6837\u654f\u6377.", "\u795e\u58eb\u5fc3\u6cd5|\u4fee\u70bc\u795e\u58eb\u7684\u4e0a\u4e58\u5fc3\u6cd5\u53ef\u4ee5\u589e\u52a0\u529b\u91cf,\u4f53\u529b,\u8fd0\u6c14\u901f\u5ea6."};
